<?php require_once "config/database.php";require_once "includes/functions.php";$pageTitle="Cart";$items=[];foreach($_SESSION["cart"]??[] as $id=>$q){$s=$pdo->prepare("SELECT * FROM products WHERE id=?");$s->execute([(int)$id]);if($p=$s->fetch()){$p["quantity"]=(int)$q;$items[]=$p;}}require "includes/header.php";?><section class="section"><div class="container"><div class="eyebrow">Your Selection</div><h1>Shopping Cart</h1><?php if(!$items):?><div class="empty">Your cart is empty.<br><br><a class="btn" href="products.php">Shop Watches</a></div><?php else:?><div class="cartgrid"><div><?php foreach($items as $p):?><div class="panel" style="display:flex;gap:15px;margin-bottom:15px"><img src="<?=e($p["image"])?>" style="width:150px;height:150px;object-fit:cover" alt=""><div style="flex:1"><h3><?=e($p["name"])?></h3><div class="price">₹<?=number_format((float)$p["price"],2)?></div><form action="actions/update_cart.php" method="post" class="actions"><input type="hidden" name="product_id" value="<?=$p["id"]?>"><input class="input" style="width:80px" type="number" min="1" name="quantity" value="<?=$p["quantity"]?>"><button class="btn secondary">Update</button><a class="btn danger" href="actions/remove_from_cart.php?id=<?=$p["id"]?>">Remove</a></form></div></div><?php endforeach;?></div><aside class="panel summary"><h3>Order Summary</h3><div class="row"><span>Items</span><span><?=cart_count()?></span></div><div class="row total"><b>Total</b><b class="price">₹<?=number_format(cart_total($pdo),2)?></b></div><a class="btn" style="width:100%;text-align:center;margin-top:18px" href="checkout.php">Checkout</a></aside></div><?php endif;?></div></section><?php require "includes/footer.php";?>